func TestSIM_E01_NoFaultElection(t *testing.T) {
	for seed := int64(1); seed <= 1000; seed++ {
		sim := newSimulation(seed, nil, nil)
		if err := sim.RunNoFault(200); err != nil {
			t.Fatalf("seed %d: ElectionSafety failed: %v", seed, err)
		}
		if _, _, ok := sim.Leader(); !ok {
			t.Fatalf("seed %d: no leader elected within 200 ticks", seed)
		}
	}
}

func TestSIM_E02_ForcedSplitVote(t *testing.T) {
	sim := newSimulation(1, []int{0, 0, 0, 0, 9, 9}, nil)
	if err := sim.RunNoFault(200); err != nil {
		t.Fatalf("ElectionSafety failed: %v", err)
	}
	_, term, ok := sim.Leader()
	if !ok {
		t.Fatal("no leader elected after forced split vote")
	}
	if term < 2 {
		t.Fatalf("leader term = %d, want term advanced after split vote", term)
	}
}

func TestSIM_E03_StaleLogCandidateNeverWins(t *testing.T) {
	fresh := []simulation.InitialNode{
		{ID: 2, Persistent: raft.Persistent{Log: []raft.Entry{{Index: 2, Term: 2}}}},
		{ID: 3, Persistent: raft.Persistent{Log: []raft.Entry{{Index: 2, Term: 2}}}},
	}
	sim := newSimulation(3, []int{0, 9, 9}, fresh)
	for tick := 0; tick < 10; tick++ {
		sim.Tick(1)
	}
	sim.DeliverAll()
	if err := sim.Error(); err != nil {
		t.Fatalf("ElectionSafety failed: %v", err)
	}
	if state := nodeState(t, sim, 1); state.State.Role == raft.Leader {
		t.Fatalf("stale candidate became leader in term %d", state.State.Term)
	}
}

func TestSIM_E04_PartitionLeader(t *testing.T) {
	sim := newSimulation(4, nil, nil)
	if err := sim.RunNoFault(200); err != nil {
		t.Fatalf("initial ElectionSafety failed: %v", err)
	}
	oldLeader, oldTerm, ok := sim.Leader()
	if !ok {
		t.Fatal("no initial leader")
	}
	majority := peersExcept(oldLeader)
	sim.Partition([]uint64{oldLeader}, majority)
	if err := sim.RunNoFault(200); err != nil {
		t.Fatalf("ElectionSafety failed after partition: %v", err)
	}

	var majorityLeader simulation.NodeState
	for _, state := range sim.Nodes() {
		if state.Alive && state.ID != oldLeader && state.State.Role == raft.Leader {
			majorityLeader = state
		}
	}
	if majorityLeader.ID == 0 {
		t.Fatal("majority side did not elect a leader")
	}
	if majorityLeader.State.Term <= oldTerm {
		t.Fatalf("majority leader term = %d, want > old term %d", majorityLeader.State.Term, oldTerm)
	}
	oldState := nodeState(t, sim, oldLeader)
	if oldState.State.Role != raft.Leader || oldState.State.Term != oldTerm {
		t.Fatalf("old leader state = role %s term %d, want leader in old term %d", oldState.State.Role, oldState.State.Term, oldTerm)
	}
}

func TestSIM_E05_CrashRestartAroundVoting(t *testing.T) {
	if err := doubleVoteScenario(); err != nil {
		t.Fatalf("scripted crash/restart scenario: %v", err)
	}
	for seed := int64(1); seed <= 1000; seed++ {
		sim := newSimulation(seed, nil, nil)
		if err := sim.RunRandom(200); err != nil {
			t.Fatalf("seed %d: ElectionSafety failed: %v", seed, err)
		}
	}
}

func TestSIM_D01_Determinism(t *testing.T) {
	for seed := int64(1); seed <= 1000; seed++ {
		first := newSimulation(seed, nil, nil)
		second := newSimulation(seed, nil, nil)
		if err := first.RunRandom(300); err != nil {
			t.Fatalf("seed %d first run: %v", seed, err)
		}
		if err := second.RunRandom(300); err != nil {
			t.Fatalf("seed %d second run: %v", seed, err)
		}
		if first.Hash() != second.Hash() {
			t.Fatalf("seed %d hash mismatch: %s != %s", seed, first.Hash(), second.Hash())
		}
	}
}

func newSimulation(seed int64, timeoutScript []int, initial []simulation.InitialNode) *simulation.Simulator {
	return simulation.New(seed, simulation.Config{
		NodeIDs:       []uint64{1, 2, 3},
		Initial:       initial,
		TimeoutScript: timeoutScript,
	})
}

func doubleVoteScenario() error {
	sim := newSimulation(5, []int{0, 9, 9, 0}, nil)
	for tick := 0; tick < 10; tick++ {
		sim.Tick(1)
	}
	if !sim.Deliver(1, 2, raft.RequestVote) || !sim.Deliver(2, 1, raft.RequestVoteResp) {
		return fmt.Errorf("could not elect node 1 with node 2's vote")
	}
	if state := nodeStateFrom(sim, 1); state.State.Role != raft.Leader {
		return fmt.Errorf("node 1 did not become leader")
	}
	if !sim.Drop(1, 3, raft.RequestVote) {
		return fmt.Errorf("could not suppress node 1 request to node 3")
	}
	if !sim.Crash(2) || !sim.Restart(2) {
		return fmt.Errorf("could not restart node 2")
	}
	for tick := 0; tick < 19; tick++ {
		sim.Tick(3)
	}
	if !sim.Deliver(3, 2, raft.RequestVote) || !sim.Deliver(2, 3, raft.RequestVoteResp) {
		return fmt.Errorf("could not deliver node 3's request through node 2")
	}
	return sim.Error()
}

func nodeState(t *testing.T, sim *simulation.Simulator, id uint64) simulation.NodeState {
	t.Helper()
	state := nodeStateFrom(sim, id)
	if state.ID == 0 {
		t.Fatalf("node %d not found", id)
	}
	return state
}

func nodeStateFrom(sim *simulation.Simulator, id uint64) simulation.NodeState {
	for _, state := range sim.Nodes() {
		if state.ID == id {
			return state
		}
	}
	return simulation.NodeState{}
}

func peersExcept(id uint64) []uint64 {
	peers := make([]uint64, 0, 2)
	for _, candidate := range []uint64{1, 2, 3} {
		if candidate != id {
			peers = append(peers, candidate)
		}
	}
	return peers
}
